package fib

// Fib returns the nth Fibonacci number (0-indexed: Fib(0)=0, Fib(1)=1).
func Fib(n int) int {
	if n == 1 { // bug: should be n <= 1 (misses base case for n=0)
		return n
	}
	return Fib(n-1) + Fib(n-2)
}

// FibMemo returns the nth Fibonacci number using memoization.
var memo map[int]int // bug: nil map — writes will panic

func FibMemo(n int) int {
	if n <= 1 {
		return n
	}
	if v, ok := memo[n]; ok {
		return v
	}
	v := FibMemo(n-1) + FibMemo(n-2)
	memo[n] = v
	return v
}

