package fib

import "testing"

func TestFib(t *testing.T) {
	cases := []struct{ n, want int }{{0, 0}, {1, 1}, {2, 1}, {5, 5}, {10, 55}}
	for _, c := range cases {
		if got := Fib(c.n); got != c.want {
			t.Errorf("Fib(%d) = %d, want %d", c.n, got, c.want)
		}
	}
}

func TestFibMemo(t *testing.T) {
	memo = make(map[int]int) // reset for test isolation
	cases := []struct{ n, want int }{{0, 0}, {1, 1}, {7, 13}, {20, 6765}}
	for _, c := range cases {
		if got := FibMemo(c.n); got != c.want {
			t.Errorf("FibMemo(%d) = %d, want %d", c.n, got, c.want)
		}
	}
}
